import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

const POLL_ATTEMPTS = 60;
const POLL_INTERVAL_MS = 500;

function uniqueVendorName(): string {
  return `LIF-03 Vendor ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function uploadDocument(api: APIRequestContext, vendorId: string, kind: "w9" | "contract") {
  const response = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${kind}.txt`,
        mimeType: "text/plain",
        buffer: Buffer.from(`${kind} sample content for LIF-03`),
      },
    },
  });
  return expectStatus<{ id: string; status: string }>(response, 201);
}

async function extractionForDocument(api: APIRequestContext, documentId: string) {
  for (let attempt = 0; attempt < POLL_ATTEMPTS; attempt++) {
    const documentResponse = await api.get(`/api/documents/${documentId}`);
    if (documentResponse.ok()) {
      const document = (await documentResponse.json()) as { status: string };
      if (document.status === "failed") {
        throw new Error(`document ${documentId} failed extraction`);
      }
      if (document.status === "extracted") {
        const extraction = await api.get(`/api/documents/${documentId}/extraction`);
        return expectStatus<{ id: string; status: string }>(extraction, 200);
      }
    }
    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
  }
  throw new Error(`document ${documentId} did not finish extraction in time`);
}

test.describe("vendor lifecycle", () => {
  test(
    "once a vendor is sent back, its other documents cannot be decided",
    { tag: "@LIF-03" },
    async ({ apiAs }) => {
      // Arrange: a member builds a vendor with a w9 and a contract, then submits it for review.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueVendorName(),
          category: "services",
          contact_email: "lif03-vendor@example.com",
        },
      });
      const vendor = await expectStatus<{ id: string }>(vendorResponse, 201);

      const w9 = await uploadDocument(member, vendor.id, "w9");
      const contract = await uploadDocument(member, vendor.id, "contract");

      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);
      await expectStatus(submitResponse, 200);

      const w9Extraction = await extractionForDocument(member, w9.id);
      const contractExtraction = await extractionForDocument(member, contract.id);

      // Arrange: the reviewer sends the vendor back by rejecting the w9 extraction.
      const rejectResponse = await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
        data: { decision: "reject", note: "W9 is illegible" },
      });
      await expectStatus(rejectResponse, 200);

      // Act: the reviewer tries to approve the contract extraction of the same vendor.
      const approveResponse = await reviewer.post(`/api/extractions/${contractExtraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert
      const body = await expectStatus<{ error: { code: string } }>(approveResponse, 409);
      expect(body.error.code).toBe("vendor_not_in_review");
    },
  );
});
